package com.absmobile.app;
import android.content.Context;import android.view.View;import android.view.MotionEvent;import android.graphics.Canvas;import android.graphics.Paint;import android.graphics.RectF;
public class ZoneOverlay extends View {
 public boolean calibration=false; private Paint p=new Paint(3); private RectF zone=new RectF(0.39f,0.28f,0.61f,0.70f); private float downX,downY; private boolean moving=false;
 public ZoneOverlay(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
 protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();RectF r=new RectF(zone.left*w,zone.top*h,zone.right*w,zone.bottom*h);p.setColor(0xCC42F5A7);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(calibration?5:3);c.drawRect(r,p);p.setStyle(Paint.Style.FILL);p.setColor(0x1742F5A7);c.drawRect(r,p);p.setColor(0xFF42F5A7);p.setTextSize(28);p.setStrokeWidth(2);c.drawLine(r.left-18,r.top,r.left+18,r.top,p);c.drawLine(r.right-18,r.top,r.right+18,r.top,p);c.drawLine(r.left-18,r.bottom,r.left+18,r.bottom,p);c.drawLine(r.right-18,r.bottom,r.right+18,r.bottom,p);p.setTextSize(14);p.setStyle(Paint.Style.FILL);c.drawText(calibration?"ZONE CALIBRATION":"STRIKE ZONE",r.left,r.top-12,p);if(calibration){p.setTextSize(12);c.drawText("DRAG TO POSITION",r.left,r.bottom+22,p);} }
 public boolean onTouchEvent(MotionEvent e){if(!calibration)return false;float x=e.getX()/getWidth(),y=e.getY()/getHeight();switch(e.getAction()){case MotionEvent.ACTION_DOWN:downX=x;downY=y;moving=zone.contains(x,y);return moving;case MotionEvent.ACTION_MOVE:if(moving){float dx=x-downX,dy=y-downY;float width=zone.width(),height=zone.height();zone.left=Math.max(0,Math.min(1-width,zone.left+dx));zone.top=Math.max(0,Math.min(1-height,zone.top+dy));zone.right=zone.left+width;zone.bottom=zone.top+height;downX=x;downY=y;invalidate();}return true;case MotionEvent.ACTION_UP:moving=false;return true;}return true;}
}
